/**
 * @param {string} s
 * @return {number}
 */
var minOperations = function(s) {
    let count = 0;

    for (let i = 0; i < s.length; i++) {
        const isEven = i % 2 === 0;
        const isOne = s[i] === '1';

        if (isEven ^ isOne) {
            count++;
        }
    }

    return Math.min(count, s.length - count);
};
